CREATE TABLE public.lockers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),camp_id uuid NOT NULL REFERENCES public.camps(id),block_id uuid NOT NULL REFERENCES public.buildings(id),floor integer NOT NULL DEFAULT 1,room_id uuid REFERENCES public.rooms(id),number text NOT NULL,type text NOT NULL DEFAULT 'Individual Locker',description text NOT NULL DEFAULT '',condition text NOT NULL DEFAULT 'Good',status text NOT NULL DEFAULT 'Available',capacity integer NOT NULL DEFAULT 1,remarks text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.lockers TO authenticated; GRANT ALL ON public.lockers TO service_role;
ALTER TABLE public.lockers ENABLE ROW LEVEL SECURITY;
CREATE POLICY locker_read ON public.lockers FOR SELECT TO authenticated USING(true);
CREATE POLICY locker_manage ON public.lockers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'camp_manager') OR public.has_role(auth.uid(),'hr_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'camp_manager') OR public.has_role(auth.uid(),'hr_admin'));
CREATE UNIQUE INDEX locker_camp_number ON public.lockers(camp_id,lower(btrim(number)));
CREATE TABLE public.locker_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),locker_id uuid NOT NULL REFERENCES public.lockers(id),employee_id uuid,employee_code text NOT NULL,employee_name text NOT NULL,department text NOT NULL DEFAULT '',project text NOT NULL DEFAULT '',allocated_on date NOT NULL,released_on date,release_condition text,key_returned boolean,remarks text NOT NULL DEFAULT '',created_by uuid NOT NULL,override_authorized boolean NOT NULL DEFAULT false,previous_allocation_id uuid REFERENCES public.locker_allocations(id),charge_mode text NOT NULL DEFAULT 'Free',charge_rate numeric NOT NULL DEFAULT 0,deposit numeric NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.locker_allocations TO authenticated; GRANT ALL ON public.locker_allocations TO service_role;
ALTER TABLE public.locker_allocations ENABLE ROW LEVEL SECURITY; CREATE POLICY allocation_read ON public.locker_allocations FOR SELECT TO authenticated USING(true);
CREATE TABLE public.locker_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),locker_id uuid NOT NULL REFERENCES public.lockers(id),allocation_id uuid REFERENCES public.locker_allocations(id),kind text NOT NULL,effective_date date NOT NULL DEFAULT CURRENT_DATE,actor uuid,previous_value jsonb,new_value jsonb,remarks text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.locker_events TO authenticated; GRANT ALL ON public.locker_events TO service_role;
ALTER TABLE public.locker_events ENABLE ROW LEVEL SECURITY; CREATE POLICY event_read ON public.locker_events FOR SELECT TO authenticated USING(true);
CREATE TABLE public.locker_configuration(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),camp_id uuid NOT NULL UNIQUE REFERENCES public.camps(id),charge_mode text NOT NULL DEFAULT 'Free',rate numeric NOT NULL DEFAULT 0,deposit numeric NOT NULL DEFAULT 0,checkout_policy text NOT NULL DEFAULT 'Manual clearance');
GRANT SELECT,INSERT,UPDATE ON public.locker_configuration TO authenticated; GRANT ALL ON public.locker_configuration TO service_role;
ALTER TABLE public.locker_configuration ENABLE ROW LEVEL SECURITY; CREATE POLICY config_read ON public.locker_configuration FOR SELECT TO authenticated USING(true); CREATE POLICY config_admin ON public.locker_configuration FOR ALL TO authenticated USING(public.has_role(auth.uid(),'super_admin')) WITH CHECK(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.locker_charge_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),allocation_id uuid NOT NULL REFERENCES public.locker_allocations(id),kind text NOT NULL,amount numeric NOT NULL,effective_date date NOT NULL,actor uuid NOT NULL,remarks text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.locker_charge_transactions TO authenticated; GRANT ALL ON public.locker_charge_transactions TO service_role;
ALTER TABLE public.locker_charge_transactions ENABLE ROW LEVEL SECURITY; CREATE POLICY charge_read ON public.locker_charge_transactions FOR SELECT TO authenticated USING(true);
CREATE OR REPLACE FUNCTION public.validate_locker() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.type NOT IN('Individual Locker','Double-door Locker','Multi-compartment Locker','Shared Locker','Custom Locker') OR NEW.status NOT IN('Available','Allocated','Under Maintenance','Damaged','Decommissioned') OR NEW.condition NOT IN('Good','Needs Repair','Damaged') OR NEW.capacity<1 OR btrim(NEW.number)='' THEN RAISE EXCEPTION 'Invalid locker details'; END IF;
IF NEW.type<>'Shared Locker' AND NEW.capacity<>1 THEN RAISE EXCEPTION 'Only shared lockers may hold multiple employees'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.buildings WHERE id=NEW.block_id AND camp_id=NEW.camp_id) OR (NEW.room_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.rooms WHERE id=NEW.room_id AND camp_id=NEW.camp_id AND building_id=NEW.block_id AND floor=NEW.floor)) THEN RAISE EXCEPTION 'Locker location does not match saved infrastructure'; END IF;
IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.locker_allocations WHERE locker_id=NEW.id AND released_on IS NULL) AND (NEW.status<>'Allocated' OR NEW.camp_id<>OLD.camp_id OR NEW.block_id<>OLD.block_id OR NEW.floor<>OLD.floor OR NEW.room_id IS DISTINCT FROM OLD.room_id OR NEW.capacity<(SELECT count(*) FROM public.locker_allocations WHERE locker_id=NEW.id AND released_on IS NULL)) THEN RAISE EXCEPTION 'Release allocations before changing location or availability'; END IF;
IF NEW.status='Allocated' AND NOT EXISTS(SELECT 1 FROM public.locker_allocations WHERE locker_id=NEW.id AND released_on IS NULL) THEN RAISE EXCEPTION 'Use Allocate Locker'; END IF;
RETURN NEW; END $$;
CREATE TRIGGER locker_validate BEFORE INSERT OR UPDATE ON public.lockers FOR EACH ROW EXECUTE FUNCTION public.validate_locker();
CREATE OR REPLACE FUNCTION public.audit_locker() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.locker_events(locker_id,kind,actor,previous_value,new_value,remarks) VALUES(NEW.id,CASE WHEN TG_OP='INSERT' THEN 'Creation' WHEN NEW.status IS DISTINCT FROM OLD.status THEN 'Status Change' ELSE 'Master Edit' END,auth.uid(),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW),NEW.remarks); RETURN NEW; END $$;
CREATE TRIGGER locker_audit AFTER INSERT OR UPDATE ON public.lockers FOR EACH ROW EXECUTE FUNCTION public.audit_locker();
CREATE OR REPLACE FUNCTION public.locker_allocate(p_locker uuid,p_employee uuid,p_date date,p_remarks text DEFAULT '',p_override boolean DEFAULT false,p_previous uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l record;e record;c record;a uuid;BEGIN
IF NOT(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'camp_manager') OR public.has_role(auth.uid(),'hr_admin')) THEN RAISE EXCEPTION 'Not authorized'; END IF;
PERFORM 1 FROM public.employees WHERE id=p_employee FOR UPDATE; SELECT * INTO e FROM public.employees WHERE id=p_employee;
SELECT * INTO l FROM public.lockers WHERE id=p_locker FOR UPDATE;
IF l.id IS NULL OR e.id IS NULL OR p_date IS NULL OR p_date>CURRENT_DATE THEN RAISE EXCEPTION 'Invalid allocation'; END IF;
IF l.status NOT IN('Available','Allocated') OR l.condition<>'Good' OR (SELECT count(*) FROM public.locker_allocations WHERE locker_id=l.id AND released_on IS NULL)>=l.capacity THEN RAISE EXCEPTION 'Locker unavailable or full'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.check_ins ci WHERE ci.employee_id=p_employee AND ci.camp_id=l.camp_id AND ci.check_in_date::date<=p_date AND NOT EXISTS(SELECT 1 FROM public.check_outs co WHERE co.employee_id=ci.employee_id AND co.check_out_date>=ci.check_in_date AND co.check_out_date::date<=p_date) AND NOT EXISTS(SELECT 1 FROM public.check_ins n WHERE n.employee_id=ci.employee_id AND n.check_in_date>ci.check_in_date AND n.check_in_date::date<=p_date)) THEN RAISE EXCEPTION 'Employee must have a saved stay in this camp'; END IF;
IF EXISTS(SELECT 1 FROM public.locker_allocations WHERE locker_id=l.id AND employee_id=p_employee AND released_on IS NULL) THEN RAISE EXCEPTION 'Employee already has this locker'; END IF;
IF l.type<>'Shared Locker' AND EXISTS(SELECT 1 FROM public.locker_allocations a JOIN public.lockers k ON k.id=a.locker_id WHERE a.employee_id=p_employee AND a.released_on IS NULL AND k.type<>'Shared Locker') AND NOT(p_override AND public.has_role(auth.uid(),'super_admin')) THEN RAISE EXCEPTION 'Duplicate individual locker requires super-admin authorization'; END IF;
SELECT * INTO c FROM public.locker_configuration WHERE camp_id=l.camp_id;
INSERT INTO public.locker_allocations(locker_id,employee_id,employee_code,employee_name,department,project,allocated_on,remarks,created_by,override_authorized,previous_allocation_id,charge_mode,charge_rate,deposit) VALUES(l.id,e.id,e.employee_id,e.name,COALESCE(e.department,''),COALESCE(e.project,''),p_date,COALESCE(p_remarks,''),auth.uid(),p_override AND public.has_role(auth.uid(),'super_admin'),p_previous,COALESCE(c.charge_mode,'Free'),COALESCE(c.rate,0),COALESCE(c.deposit,0)) RETURNING id INTO a;
UPDATE public.lockers SET status='Allocated' WHERE id=l.id;
INSERT INTO public.locker_events(locker_id,allocation_id,kind,effective_date,actor,new_value,remarks) VALUES(l.id,a,'Allocation',p_date,auth.uid(),jsonb_build_object('employee',e.employee_id),COALESCE(p_remarks,''));
IF COALESCE(c.deposit,0)>0 THEN INSERT INTO public.locker_charge_transactions(allocation_id,kind,amount,effective_date,actor) VALUES(a,'Deposit',c.deposit,p_date,auth.uid()); END IF;
RETURN a; END $$;
CREATE OR REPLACE FUNCTION public.locker_release(p_allocation uuid,p_date date,p_condition text,p_key boolean,p_remarks text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; BEGIN
IF NOT(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'camp_manager') OR public.has_role(auth.uid(),'hr_admin')) THEN RAISE EXCEPTION 'Not authorized'; END IF;
SELECT * INTO a FROM public.locker_allocations WHERE id=p_allocation; PERFORM 1 FROM public.lockers WHERE id=a.locker_id FOR UPDATE; SELECT * INTO a FROM public.locker_allocations WHERE id=p_allocation FOR UPDATE;
IF a.id IS NULL OR a.released_on IS NOT NULL OR p_date<a.allocated_on OR p_date>CURRENT_DATE OR p_condition NOT IN('Good','Needs Repair','Damaged') OR p_key IS NULL THEN RAISE EXCEPTION 'Invalid release'; END IF;
UPDATE public.locker_allocations SET released_on=p_date,release_condition=p_condition,key_returned=p_key WHERE id=a.id;
UPDATE public.lockers SET condition=p_condition,status=CASE WHEN p_condition='Damaged' THEN 'Damaged' WHEN p_condition='Needs Repair' OR NOT p_key THEN 'Under Maintenance' WHEN EXISTS(SELECT 1 FROM public.locker_allocations WHERE locker_id=a.locker_id AND released_on IS NULL) THEN 'Allocated' ELSE 'Available' END WHERE id=a.locker_id;
INSERT INTO public.locker_events(locker_id,allocation_id,kind,effective_date,actor,previous_value,new_value,remarks) VALUES(a.locker_id,a.id,'Release',p_date,auth.uid(),to_jsonb(a),jsonb_build_object('condition',p_condition,'key_returned',p_key),COALESCE(p_remarks,'')); END $$;
CREATE OR REPLACE FUNCTION public.locker_transfer(p_allocation uuid,p_target uuid,p_date date,p_remarks text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record;n uuid;BEGIN
SELECT * INTO a FROM public.locker_allocations WHERE id=p_allocation;
PERFORM 1 FROM public.lockers WHERE id IN(a.locker_id,p_target) ORDER BY id FOR UPDATE;
IF a.id IS NULL OR a.locker_id=p_target THEN RAISE EXCEPTION 'Select another available locker'; END IF;
PERFORM public.locker_release(a.id,p_date,'Good',true,p_remarks);
n:=public.locker_allocate(p_target,a.employee_id,p_date,p_remarks,false,a.id);
INSERT INTO public.locker_events(locker_id,allocation_id,kind,effective_date,actor,previous_value,new_value,remarks) VALUES(p_target,n,'Transfer',p_date,auth.uid(),jsonb_build_object('locker',a.locker_id),jsonb_build_object('locker',p_target),COALESCE(p_remarks,'')); RETURN n;END $$;
CREATE OR REPLACE FUNCTION public.locker_maintenance(p_locker uuid,p_date date,p_status text,p_condition text,p_remarks text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'camp_manager') OR public.has_role(auth.uid(),'maintenance_supervisor')) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF p_date IS NULL OR p_date>CURRENT_DATE OR p_status NOT IN('Available','Under Maintenance','Damaged','Decommissioned') THEN RAISE EXCEPTION 'Invalid maintenance'; END IF;
UPDATE public.lockers SET status=p_status,condition=p_condition,remarks=COALESCE(p_remarks,'') WHERE id=p_locker;
INSERT INTO public.locker_events(locker_id,kind,effective_date,actor,new_value,remarks) VALUES(p_locker,'Maintenance',p_date,auth.uid(),jsonb_build_object('status',p_status,'condition',p_condition),COALESCE(p_remarks,'')); END $$;
CREATE OR REPLACE FUNCTION public.locker_refund(p_allocation uuid,p_amount numeric,p_date date,p_remarks text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record;BEGIN
IF NOT(public.has_role(auth.uid(),'super_admin') OR public.has_role(auth.uid(),'hr_admin')) THEN RAISE EXCEPTION 'Not authorized'; END IF;
SELECT * INTO a FROM public.locker_allocations WHERE id=p_allocation FOR UPDATE;
IF a.id IS NULL OR p_amount<=0 OR p_date IS NULL OR p_date>CURRENT_DATE OR p_amount> a.deposit-COALESCE((SELECT sum(amount) FROM public.locker_charge_transactions WHERE allocation_id=a.id AND kind='Refund'),0) THEN RAISE EXCEPTION 'Invalid refund amount'; END IF;
INSERT INTO public.locker_charge_transactions(allocation_id,kind,amount,effective_date,actor,remarks) VALUES(a.id,'Refund',p_amount,p_date,auth.uid(),COALESCE(p_remarks,''));
INSERT INTO public.locker_events(locker_id,allocation_id,kind,effective_date,actor,new_value,remarks) VALUES(a.locker_id,a.id,'Deposit Refund',p_date,auth.uid(),jsonb_build_object('amount',p_amount),COALESCE(p_remarks,'')); END $$;
REVOKE ALL ON FUNCTION public.locker_allocate(uuid,uuid,date,text,boolean,uuid),public.locker_release(uuid,date,text,boolean,text),public.locker_transfer(uuid,uuid,date,text),public.locker_maintenance(uuid,date,text,text,text),public.locker_refund(uuid,numeric,date,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.locker_allocate(uuid,uuid,date,text,boolean,uuid),public.locker_release(uuid,date,text,boolean,text),public.locker_transfer(uuid,uuid,date,text),public.locker_maintenance(uuid,date,text,text,text),public.locker_refund(uuid,numeric,date,text) TO authenticated;